(() => {
  const clean = (s) => (s || '').trim();
  const 新体 = [...document.body.children].map((e) => (e.tagName + '.' + (e.className || '').toString().slice(0, 40) + ':' + clean(e.innerText).slice(0, 90)));
  const inp = [...document.querySelectorAll('input')].find((x) => (x.placeholder || '').includes('选择所属行业'));
  return {body子节点: 新体.slice(-8), 行业框值: inp ? clean(inp.value) : '没了', 焦点是它: document.activeElement === inp};
})()

(() => {
  const inp = [...document.querySelectorAll('input')].find((x) => (x.placeholder || '').includes('选择所属行业'));
  if (!inp) return '没了';
  inp.focus();
  for (const t of ['keydown', 'keyup']) { inp.dispatchEvent(new KeyboardEvent(t, {bubbles: true, key: 'Enter', code: 'Enter', keyCode: 13})); }
  for (const t of ['mousedown', 'mouseup', 'click', 'focus', 'blur']) { inp.dispatchEvent(new Event(t, {bubbles: true})); }
  return '敲过 Enter 也派发过一轮';
})()

(() => {
  const clean = (s) => (s || '').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2; };
  const d = [...document.querySelectorAll('.dialog-wrap, [class*=dialog]')].filter((e) => vis(e));
  return {浮层: d.map((e) => (e.className || '').toString().slice(0, 50) + ':' + clean(e.innerText).slice(0, 80)).slice(0, 6)};
})()
